-- PAM synthetic dataset seed (generated; see manifest.json for checksums)
BEGIN;
CREATE SCHEMA IF NOT EXISTS gt;
CREATE TABLE user_profile (
	user_id VARCHAR(32) NOT NULL, 
	display_name VARCHAR(80) NOT NULL, 
	city VARCHAR(40) NOT NULL, 
	state VARCHAR(2) NOT NULL, 
	city_tier SMALLINT NOT NULL, 
	persona VARCHAR(16) NOT NULL, 
	income_band VARCHAR(10) NOT NULL, 
	monthly_income_paise BIGINT NOT NULL, 
	household_size SMALLINT NOT NULL, 
	timezone VARCHAR(40) NOT NULL, 
	created_on DATE NOT NULL, 
	CONSTRAINT pk_user_profile PRIMARY KEY (user_id), 
	CONSTRAINT ck_user_profile_income_nonneg CHECK (monthly_income_paise >= 0), 
	CONSTRAINT ck_user_profile_household_range CHECK (household_size BETWEEN 1 AND 8), 
	CONSTRAINT ck_user_profile_city_tier_allowed CHECK (city_tier IN (1, 2, 3)), 
	CONSTRAINT ck_user_profile_persona_allowed CHECK (persona IN ('SALARIED', 'SELF_EMPLOYED', 'RETIRED')), 
	CONSTRAINT ck_user_profile_income_band_allowed CHECK (income_band IN ('LOW', 'MID', 'HIGH', 'AFFLUENT')), 
	CONSTRAINT ck_user_profile_timezone_allowed CHECK (timezone IN ('Asia/Kolkata'))
);
CREATE TABLE category (
	category_code VARCHAR(40) NOT NULL, 
	name VARCHAR(60) NOT NULL, 
	group_code VARCHAR(12) NOT NULL, 
	kind VARCHAR(10) NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	replaced_by VARCHAR(40), 
	CONSTRAINT pk_category PRIMARY KEY (category_code), 
	CONSTRAINT ck_category_dates CHECK (effective_to IS NULL OR effective_to >= effective_from), 
	CONSTRAINT ck_category_group_code_allowed CHECK (group_code IN ('INCOME', 'ESSENTIALS', 'LIFESTYLE', 'OTHER', 'FINANCIAL')), 
	CONSTRAINT ck_category_kind_allowed CHECK (kind IN ('INCOME', 'EXPENSE', 'TRANSFER', 'UNKNOWN')), 
	CONSTRAINT fk_category_replaced_by FOREIGN KEY(replaced_by) REFERENCES category (category_code)
);
CREATE TABLE category_synonym (
	synonym VARCHAR(40) NOT NULL, 
	category_code VARCHAR(40) NOT NULL, 
	CONSTRAINT pk_category_synonym PRIMARY KEY (synonym), 
	CONSTRAINT fk_category_synonym_category_code FOREIGN KEY(category_code) REFERENCES category (category_code)
);
CREATE TABLE merchant (
	merchant_id VARCHAR(32) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	default_category_code VARCHAR(40) NOT NULL, 
	vpa VARCHAR(64), 
	is_online BOOLEAN NOT NULL, 
	CONSTRAINT pk_merchant PRIMARY KEY (merchant_id), 
	CONSTRAINT fk_merchant_default_category_code FOREIGN KEY(default_category_code) REFERENCES category (category_code), 
	CONSTRAINT uq_merchant_vpa UNIQUE (vpa)
);
CREATE TABLE merchant_alias (
	alias VARCHAR(60) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	CONSTRAINT pk_merchant_alias PRIMARY KEY (alias), 
	CONSTRAINT fk_merchant_alias_merchant_id FOREIGN KEY(merchant_id) REFERENCES merchant (merchant_id)
);
CREATE TABLE merchant_category (
	merchant_id VARCHAR(32) NOT NULL, 
	category_code VARCHAR(40) NOT NULL, 
	CONSTRAINT pk_merchant_category PRIMARY KEY (merchant_id, category_code), 
	CONSTRAINT fk_merchant_category_merchant_id FOREIGN KEY(merchant_id) REFERENCES merchant (merchant_id), 
	CONSTRAINT fk_merchant_category_category_code FOREIGN KEY(category_code) REFERENCES category (category_code)
);
CREATE TABLE category_rule (
	rule_id VARCHAR(32) NOT NULL, 
	version SMALLINT NOT NULL, 
	priority SMALLINT NOT NULL, 
	category_code VARCHAR(40) NOT NULL, 
	merchant_id VARCHAR(32), 
	pattern VARCHAR(200), 
	channel VARCHAR(10), 
	direction VARCHAR(3) NOT NULL, 
	account_type VARCHAR(12), 
	confidence NUMERIC(3, 2) NOT NULL, 
	effective_from TIMESTAMP WITH TIME ZONE NOT NULL, 
	retired_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(120) NOT NULL, 
	note TEXT, 
	CONSTRAINT pk_category_rule PRIMARY KEY (rule_id, version), 
	CONSTRAINT ck_category_rule_has_condition CHECK (merchant_id IS NOT NULL OR pattern IS NOT NULL OR channel IS NOT NULL OR account_type IS NOT NULL), 
	CONSTRAINT ck_category_rule_confidence_range CHECK (confidence BETWEEN 0 AND 1), 
	CONSTRAINT ck_category_rule_channel_allowed CHECK (channel IN ('UPI', 'IMPS', 'NEFT', 'RTGS', 'NACH', 'CARD_POS', 'CARD_ECOM', 'ATM', 'BBPS', 'INTERNAL')), 
	CONSTRAINT ck_category_rule_direction_allowed CHECK (direction IN ('DR', 'CR', 'ANY')), 
	CONSTRAINT ck_category_rule_account_type_allowed CHECK (account_type IN ('SAVINGS', 'CREDIT_CARD')), 
	CONSTRAINT fk_category_rule_category_code FOREIGN KEY(category_code) REFERENCES category (category_code), 
	CONSTRAINT fk_category_rule_merchant_id FOREIGN KEY(merchant_id) REFERENCES merchant (merchant_id)
);
CREATE TABLE account (
	account_id VARCHAR(32) NOT NULL, 
	user_id VARCHAR(32) NOT NULL, 
	account_type VARCHAR(12) NOT NULL, 
	bank_code VARCHAR(4) NOT NULL, 
	masked_number VARCHAR(20) NOT NULL, 
	vpa VARCHAR(64), 
	currency VARCHAR(3) NOT NULL, 
	opened_on DATE NOT NULL, 
	closed_on DATE, 
	status VARCHAR(8) NOT NULL, 
	opening_balance_paise BIGINT NOT NULL, 
	credit_limit_paise BIGINT, 
	CONSTRAINT pk_account PRIMARY KEY (account_id), 
	CONSTRAINT ck_account_close_after_open CHECK (closed_on IS NULL OR closed_on >= opened_on), 
	CONSTRAINT ck_account_status_matches_close CHECK ((status = 'CLOSED') = (closed_on IS NOT NULL)), 
	CONSTRAINT ck_account_account_type_allowed CHECK (account_type IN ('SAVINGS', 'CREDIT_CARD')), 
	CONSTRAINT ck_account_bank_code_allowed CHECK (bank_code IN ('SBIN', 'HDFC', 'ICIC', 'UTIB', 'KKBK', 'BARB', 'PUNB', 'CNRB')), 
	CONSTRAINT ck_account_currency_allowed CHECK (currency IN ('INR')), 
	CONSTRAINT ck_account_status_allowed CHECK (status IN ('ACTIVE', 'CLOSED')), 
	CONSTRAINT fk_account_user_id FOREIGN KEY(user_id) REFERENCES user_profile (user_id), 
	CONSTRAINT uq_account_vpa UNIQUE (vpa)
);
CREATE TABLE account_holder (
	account_id VARCHAR(32) NOT NULL, 
	user_id VARCHAR(32) NOT NULL, 
	holder_role VARCHAR(8) NOT NULL, 
	since DATE NOT NULL, 
	CONSTRAINT pk_account_holder PRIMARY KEY (account_id, user_id), 
	CONSTRAINT ck_account_holder_holder_role_allowed CHECK (holder_role IN ('PRIMARY', 'JOINT')), 
	CONSTRAINT fk_account_holder_account_id FOREIGN KEY(account_id) REFERENCES account (account_id), 
	CONSTRAINT fk_account_holder_user_id FOREIGN KEY(user_id) REFERENCES user_profile (user_id)
);
CREATE TABLE account_event (
	event_id VARCHAR(32) NOT NULL, 
	account_id VARCHAR(32) NOT NULL, 
	event_type VARCHAR(8) NOT NULL, 
	event_date DATE NOT NULL, 
	detail TEXT, 
	CONSTRAINT pk_account_event PRIMARY KEY (event_id), 
	CONSTRAINT ck_account_event_event_type_allowed CHECK (event_type IN ('OPENED', 'CLOSED')), 
	CONSTRAINT fk_account_event_account_id FOREIGN KEY(account_id) REFERENCES account (account_id)
);
CREATE TABLE account_balance_monthly (
	account_id VARCHAR(32) NOT NULL, 
	month VARCHAR(7) NOT NULL, 
	opening_paise BIGINT NOT NULL, 
	credits_paise BIGINT NOT NULL, 
	debits_paise BIGINT NOT NULL, 
	closing_paise BIGINT NOT NULL, 
	CONSTRAINT pk_account_balance_monthly PRIMARY KEY (account_id, month), 
	CONSTRAINT ck_account_balance_monthly_reconciles CHECK (opening_paise + credits_paise + debits_paise = closing_paise), 
	CONSTRAINT ck_account_balance_monthly_signs CHECK (credits_paise >= 0 AND debits_paise <= 0), 
	CONSTRAINT fk_account_balance_monthly_account_id FOREIGN KEY(account_id) REFERENCES account (account_id)
);
CREATE TABLE txn (
	txn_id VARCHAR(32) NOT NULL, 
	account_id VARCHAR(32) NOT NULL, 
	user_id VARCHAR(32) NOT NULL, 
	posted_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	amount_paise BIGINT NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	channel VARCHAR(10) NOT NULL, 
	descriptor VARCHAR(160) NOT NULL, 
	counterparty_vpa VARCHAR(64), 
	reference_no VARCHAR(24), 
	CONSTRAINT pk_txn PRIMARY KEY (txn_id), 
	CONSTRAINT ck_txn_nonzero CHECK (amount_paise <> 0), 
	CONSTRAINT ck_txn_currency_allowed CHECK (currency IN ('INR')), 
	CONSTRAINT ck_txn_channel_allowed CHECK (channel IN ('UPI', 'IMPS', 'NEFT', 'RTGS', 'NACH', 'CARD_POS', 'CARD_ECOM', 'ATM', 'BBPS', 'INTERNAL')), 
	CONSTRAINT fk_txn_account_id FOREIGN KEY(account_id) REFERENCES account (account_id), 
	CONSTRAINT fk_txn_user_id FOREIGN KEY(user_id) REFERENCES user_profile (user_id)
);
CREATE INDEX ix_txn_account_posted ON txn (account_id, posted_at);
CREATE INDEX ix_txn_user_posted ON txn (user_id, posted_at);
CREATE TABLE budget (
	budget_id VARCHAR(64) NOT NULL, 
	version SMALLINT NOT NULL, 
	user_id VARCHAR(32) NOT NULL, 
	month VARCHAR(7) NOT NULL, 
	category_code VARCHAR(40) NOT NULL, 
	amount_paise BIGINT NOT NULL, 
	submitted_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_budget PRIMARY KEY (budget_id, version), 
	CONSTRAINT ck_budget_positive CHECK (amount_paise > 0), 
	CONSTRAINT fk_budget_user_id FOREIGN KEY(user_id) REFERENCES user_profile (user_id)
);
CREATE TABLE gt.recurring_truth (
	truth_series_id VARCHAR(32) NOT NULL, 
	user_id VARCHAR(32) NOT NULL, 
	account_id VARCHAR(32) NOT NULL, 
	series_type VARCHAR(12) NOT NULL, 
	counterparty VARCHAR(80) NOT NULL, 
	cadence VARCHAR(10) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	status_at_end VARCHAR(8) NOT NULL, 
	CONSTRAINT pk_recurring_truth PRIMARY KEY (truth_series_id), 
	CONSTRAINT ck_recurring_truth_series_type_allowed CHECK (series_type IN ('SALARY', 'RENT', 'SUBSCRIPTION', 'EMI', 'UTILITY', 'INTEREST')), 
	CONSTRAINT ck_recurring_truth_cadence_allowed CHECK (cadence IN ('MONTHLY', 'QUARTERLY')), 
	CONSTRAINT ck_recurring_truth_status_at_end_allowed CHECK (status_at_end IN ('ACTIVE', 'ENDED')), 
	CONSTRAINT fk_recurring_truth_user_id FOREIGN KEY(user_id) REFERENCES user_profile (user_id), 
	CONSTRAINT fk_recurring_truth_account_id FOREIGN KEY(account_id) REFERENCES account (account_id)
);
CREATE TABLE gt.txn_label (
	txn_id VARCHAR(32) NOT NULL, 
	true_merchant_id VARCHAR(32), 
	true_category_code VARCHAR(40) NOT NULL, 
	true_kind VARCHAR(10) NOT NULL, 
	true_link_txn_id VARCHAR(32), 
	true_series_id VARCHAR(32), 
	true_local_month VARCHAR(7) NOT NULL, 
	CONSTRAINT pk_txn_label PRIMARY KEY (txn_id), 
	CONSTRAINT ck_txn_label_true_kind_allowed CHECK (true_kind IN ('EXPENSE', 'INCOME', 'TRANSFER', 'REFUND', 'REVERSAL')), 
	CONSTRAINT fk_txn_label_txn_id FOREIGN KEY(txn_id) REFERENCES txn (txn_id), 
	CONSTRAINT fk_txn_label_true_merchant_id FOREIGN KEY(true_merchant_id) REFERENCES merchant (merchant_id), 
	CONSTRAINT fk_txn_label_true_category_code FOREIGN KEY(true_category_code) REFERENCES category (category_code), 
	CONSTRAINT fk_txn_label_true_link_txn_id FOREIGN KEY(true_link_txn_id) REFERENCES txn (txn_id), 
	CONSTRAINT fk_txn_label_true_series_id FOREIGN KEY(true_series_id) REFERENCES gt.recurring_truth (truth_series_id)
);
CREATE TABLE gt.anomaly (
	anomaly_id VARCHAR(32) NOT NULL, 
	issue_type VARCHAR(28) NOT NULL, 
	entity_type VARCHAR(8) NOT NULL, 
	entity_id VARCHAR(64) NOT NULL, 
	related_ids TEXT, 
	expected_decision VARCHAR(60) NOT NULL, 
	expected_date DATE, 
	note TEXT NOT NULL, 
	CONSTRAINT pk_anomaly PRIMARY KEY (anomaly_id), 
	CONSTRAINT ck_anomaly_issue_type_allowed CHECK (issue_type IN ('TRANSFER_DOUBLE_COUNT', 'REFUND_AS_EXPENSE', 'RECURRING_SKIP', 'RECURRING_NOT_SKIP', 'TZ_BOUNDARY', 'BUDGET_CATEGORY_MISMATCH')), 
